60			{"start equals deadline", func(in *CreateVoteInput) { in.StartAt = 200 }, ErrInvalidProposal},
61			{"deadline after timelock", func(in *CreateVoteInput) { in.TimelockEnd = 199 }, ErrInvalidProposal},
