415			"b": {"b", "c"},
416			"c": {"c"},
417			"d": {"d", "c"},
418			"e": {"e"},
419		}
420		wantHead := map[string]string{"a": "c", "b": "c", "c": "c", "d": "c", "e": "e"}
421		for _, m := range view.Members {
422			if !equalStrings(m.Path, wantPath[m.ID]) {
423				t.Errorf("member %s path=%v want %v", m.ID, m.Path, wantPath[m.ID])
424			}
425			if m.Delegate != wantHead[m.ID] {
426				t.Errorf("member %s head=%s want %s", m.ID, m.Delegate, wantHead[m.ID])
427			}
428		}
429	
430		// 已委托出去的成员不能直接投票；最终代表 c 归集 1+2+4+8=15。
431		if _, err := store.CastVote("gip-chain", "a", true, 5); !errors.Is(err, ErrVoteRejected) {
432			t.Fatalf("delegated member voted: %v", err)
433		}
434		if _, err := store.CastVote("gip-chain", "ghost", true, 5); !errors.Is(err, ErrVoteRejected) {
435			t.Fatalf("non-member voted: %v", err)
436		}
437		b, err := store.CastVote("gip-chain", "c", true, 5)
438		if err != nil {
439			t.Fatalf("representative vote: %v", err)
440		}
441		if b.Weight != 15 {
442			t.Fatalf("group weight=%d, want 15", b.Weight)
443		}
444		b2, err := store.CastVote("gip-chain", "c", true, 9) // 窗口外重试
445		if err != nil || b2.VotedAt != 5 || b2.Weight != 15 {
446			t.Fatalf("identical retry: %+v err=%v", b2, err)
447		}
448		if _, err := store.CastVote("gip-chain", "c", false, 5); !errors.Is(err, ErrProposalConflict) {
449			t.Fatalf("changing vote err=%v", err)
450		}
451	}
